def solve(inp):
    H,W=len(inp),len(inp[0]); seen=[[False]*W for _ in range(H)]; boxes=[]; strays=[]
    for i in range(H):
        for j in range(W):
            if inp[i][j]!=0 and not seen[i][j]:
                col=inp[i][j]; stack=[(i,j)]; comp=[]
                while stack:
                    r,c=stack.pop()
                    if not(0<=r<H and 0<=c<W) or seen[r][c] or inp[r][c]!=col: continue
                    seen[r][c]=True; comp.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): stack.append((r+dr,c+dc))
