    fillcands=[c for c,n in cnt.items() if c not in [b[0] for b in boxes] and n>0]
    # rarest colors sorted by count
    fillcands.sort(key=lambda c:(cnt[c],c))
    boxes.sort(key=lambda b:(b[1],b[0]))  # sort by size? need box order vs color order pairing
    out=[row[:] for row in inp]
    for k,(col,r0,r1,c0,c1) in enumerate(sorted(boxes,key=lambda b:(b[1],b[0]))):
        fc=fillcands[k]
        p=(r0+c0)%2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==p: out[r][c]=fc
    return out
