        if h>=3 and w>=3 and len(comp)==2*(h+w)-4 and all(inp[x][y]==0 for x in range(r0+1,r1) for y in range(c0+1,c1)):
            boxes.append((col,r0,r1,c0,c1))
    covered=set()
    for _,r0,r1,c0,c1 in boxes:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): covered.add((r,c))
    noise_cells=[(r,c) for r in range(H) for c in range(W) if inp[r][c]!=0 and (r,c) not in covered]
    nc=Counter(inp[r][c] for r,c in noise_cells)
    noise_colors=sorted(nc,key=lambda c:nc[c])
    out=[row[:] for row in inp]
    boxcols={b[0] for b in boxes}
    for r in range(H):
        for c in range(W):
            if out[r][c] not in boxcols: out[r][c]=0
    for k,(bc,r0,r1,c0,c1) in enumerate(sorted(boxes,key=lambda b:(b[2]-b[1]-1)*(b[4]-b[3]-1))):
        f=noise_colors[k]
        par=(r0+c0)%2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==par: out[r][c]=f
    return out
